package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"sort"
	"sync"
	"time"

	maelstrom "github.com/jepsen-io/maelstrom/demo/go"
)

const (
	forwardType = "kafka_forward"
	forwardOK   = "kafka_forward_ok"
	maxPollSize = 128
)

// pair is encoded as the Kafka wire format [offset, value].
type pair struct {
	offset int
	value  json.RawMessage
}

func (p pair) MarshalJSON() ([]byte, error) {
	offset, err := json.Marshal(p.offset)
	if err != nil {
		return nil, err
	}
	value := p.value
	if len(value) == 0 {
		value = json.RawMessage("null")
	}
	return []byte(fmt.Sprintf("[%s,%s]", offset, value)), nil
}

type sendRequest struct {
	Type string          `json:"type"`
	Key  string          `json:"key"`
	Msg  json.RawMessage `json:"msg"`
}

type pollRequest struct {
	Type    string         `json:"type"`
	Offsets map[string]int `json:"offsets"`
}

type commitRequest struct {
	Type    string         `json:"type"`
	Offsets map[string]int `json:"offsets"`
}

type listRequest struct {
	Type string   `json:"type"`
	Keys []string `json:"keys"`
}

type forwardRequest struct {
	Type    string          `json:"type"`
	Request json.RawMessage `json:"request"`
}

// store contains the authoritative logs and committed offsets. All mutations
// are serialized so that every append receives a unique, increasing offset.
type store struct {
	mu        sync.Mutex
	logs      map[string][]json.RawMessage
	committed map[string]int
}

func newStore() *store {
	return &store{
		logs:      make(map[string][]json.RawMessage),
		committed: make(map[string]int),
	}
}

func (s *store) send(key string, value json.RawMessage) int {
	s.mu.Lock()
	defer s.mu.Unlock()

	// The request body is owned by its handler, so retain an independent copy.
	v := make(json.RawMessage, len(value))
	copy(v, value)
	offset := len(s.logs[key])
	s.logs[key] = append(s.logs[key], v)
	return offset
}

func (s *store) poll(offsets map[string]int) map[string][]pair {
	s.mu.Lock()
	defer s.mu.Unlock()

	result := make(map[string][]pair)
	for key, requested := range offsets {
		values := s.logs[key]
		if len(values) == 0 {
			continue
		}
		if requested < 0 {
			requested = 0
		}

		// Logs normally have dense offsets. Use a search nevertheless so that
		// the first value at or after the requested offset is returned.
		start := sort.Search(len(values), func(i int) bool {
			return i >= requested
		})
		if start == len(values) {
			continue
		}
		end := start + maxPollSize
		if end > len(values) {
			end = len(values)
		}
		items := make([]pair, 0, end-start)
		for i := start; i < end; i++ {
			items = append(items, pair{offset: i, value: values[i]})
		}
		result[key] = items
	}
	return result
}

func (s *store) commit(offsets map[string]int) {
	s.mu.Lock()
	defer s.mu.Unlock()
	for key, offset := range offsets {
		if old, ok := s.committed[key]; !ok || offset > old {
			s.committed[key] = offset
		}
	}
}

func (s *store) list(keys []string) map[string]int {
	s.mu.Lock()
	defer s.mu.Unlock()
	result := make(map[string]int)
	for _, key := range keys {
		if offset, ok := s.committed[key]; ok {
			result[key] = offset
		}
	}
	return result
}

type application struct {
	node    *maelstrom.Node
	store   *store
	leader  string
	leaderM sync.Mutex
}

func main() {
	node := maelstrom.NewNode()
	app := &application{node: node, store: newStore()}

	node.Handle("init", app.onInit)
	node.Handle("send", app.onSend)
	node.Handle("poll", app.onPoll)
	node.Handle("commit_offsets", app.onCommit)
	node.Handle("list_committed_offsets", app.onList)
	node.Handle(forwardType, app.onForward)

	if err := node.Run(); err != nil {
		log.Fatalf("node failed: %v", err)
	}
}

func (a *application) onInit(msg maelstrom.Message) error {
	ids := a.node.NodeIDs()
	if len(ids) == 0 {
		return fmt.Errorf("init contained no node IDs")
	}
	a.leaderM.Lock()
	a.leader = ids[0]
	a.leaderM.Unlock()
	log.Printf("initialized as %s; leader is %s", a.node.ID(), ids[0])
	return nil
}

func (a *application) leaderID() string {
	a.leaderM.Lock()
	defer a.leaderM.Unlock()
	return a.leader
}

func (a *application) onSend(msg maelstrom.Message) error {
	var req sendRequest
	if err := json.Unmarshal(msg.Body, &req); err != nil {
		return fmt.Errorf("decode send request: %w", err)
	}
	if a.node.ID() != a.leaderID() {
		return a.forward(msg, req)
	}
	offset := a.store.send(req.Key, req.Msg)
	return a.node.Reply(msg, map[string]any{
		"type":   "send_ok",
		"offset": offset,
	})
}

func (a *application) onPoll(msg maelstrom.Message) error {
	var req pollRequest
	if err := json.Unmarshal(msg.Body, &req); err != nil {
		return fmt.Errorf("decode poll request: %w", err)
	}
	if a.node.ID() != a.leaderID() {
		return a.forward(msg, req)
	}
	return a.node.Reply(msg, map[string]any{
		"type": "poll_ok",
		"msgs": a.store.poll(req.Offsets),
	})
}

func (a *application) onCommit(msg maelstrom.Message) error {
	var req commitRequest
	if err := json.Unmarshal(msg.Body, &req); err != nil {
		return fmt.Errorf("decode commit_offsets request: %w", err)
	}
	if a.node.ID() != a.leaderID() {
		return a.forward(msg, req)
	}
	a.store.commit(req.Offsets)
	return a.node.Reply(msg, map[string]any{"type": "commit_offsets_ok"})
}

func (a *application) onList(msg maelstrom.Message) error {
	var req listRequest
	if err := json.Unmarshal(msg.Body, &req); err != nil {
		return fmt.Errorf("decode list_committed_offsets request: %w", err)
	}
	if a.node.ID() != a.leaderID() {
		return a.forward(msg, req)
	}
	return a.node.Reply(msg, map[string]any{
		"type":    "list_committed_offsets_ok",
		"offsets": a.store.list(req.Keys),
	})
}

// forward asks the elected leader to execute a request and relays its result.
// This gives both nodes exactly the same view even when clients alternate
// between them.
func (a *application) forward(msg maelstrom.Message, request any) error {
	encoded, err := json.Marshal(request)
	if err != nil {
		return fmt.Errorf("encode forwarded request: %w", err)
	}
	ctx, cancel := context.WithTimeout(context.Background(), 15*time.Second)
	defer cancel()
	resp, err := a.node.SyncRPC(ctx, a.leaderID(), forwardRequest{
		Type:    forwardType,
		Request: encoded,
	})
	if err != nil {
		return fmt.Errorf("forward request to leader: %w", err)
	}
	var body struct {
		Type   string          `json:"type"`
		Result json.RawMessage `json:"result"`
	}
	if err := json.Unmarshal(resp.Body, &body); err != nil {
		return fmt.Errorf("decode leader response: %w", err)
	}
	if body.Type != forwardOK {
		return fmt.Errorf("unexpected leader response type %q", body.Type)
	}
	var result map[string]any
	if err := json.Unmarshal(body.Result, &result); err != nil {
		return fmt.Errorf("decode leader result: %w", err)
	}
	return a.node.Reply(msg, result)
}

func (a *application) onForward(msg maelstrom.Message) error {
	var req forwardRequest
	if err := json.Unmarshal(msg.Body, &req); err != nil {
		return fmt.Errorf("decode forward request: %w", err)
	}
	if a.node.ID() != a.leaderID() {
		return maelstrom.NewRPCError(maelstrom.NotSupported, "not the leader")
	}

	var envelope struct {
		Type string `json:"type"`
	}
	if err := json.Unmarshal(req.Request, &envelope); err != nil {
		return fmt.Errorf("decode forwarded request envelope: %w", err)
	}

	var result map[string]any
	switch envelope.Type {
	case "send":
		var r sendRequest
		if err := json.Unmarshal(req.Request, &r); err != nil {
			return err
		}
		result = map[string]any{"type": "send_ok", "offset": a.store.send(r.Key, r.Msg)}
	case "poll":
		var r pollRequest
		if err := json.Unmarshal(req.Request, &r); err != nil {
			return err
		}
		result = map[string]any{"type": "poll_ok", "msgs": a.store.poll(r.Offsets)}
	case "commit_offsets":
		var r commitRequest
		if err := json.Unmarshal(req.Request, &r); err != nil {
			return err
		}
		a.store.commit(r.Offsets)
		result = map[string]any{"type": "commit_offsets_ok"}
	case "list_committed_offsets":
		var r listRequest
		if err := json.Unmarshal(req.Request, &r); err != nil {
			return err
		}
		result = map[string]any{"type": "list_committed_offsets_ok", "offsets": a.store.list(r.Keys)}
	default:
		return maelstrom.NewRPCError(maelstrom.NotSupported, "unknown forwarded request")
	}

	encoded, err := json.Marshal(result)
	if err != nil {
		return err
	}
	return a.node.Reply(msg, map[string]any{
		"type":   forwardOK,
		"result": json.RawMessage(encoded),
	})
}

