package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"sync"
	"time"

	maelstrom "github.com/jepsen-io/maelstrom/demo/go"
)

const (
	logPrefix = "kafka-log:"
	commitKey = "kafka-committed-offsets"
	maxPoll   = 128
)

type pair struct {
	offset int
	value  json.RawMessage
}

func (p pair) MarshalJSON() ([]byte, error) {
	o, _ := json.Marshal(p.offset)
	v := p.value
	if len(v) == 0 {
		v = json.RawMessage("null")
	}
	return []byte(fmt.Sprintf("[%s,%s]", o, v)), nil
}

type sendReq struct {
	Key string          `json:"key"`
	Msg json.RawMessage `json:"msg"`
}
type pollReq struct {
	Offsets map[string]int `json:"offsets"`
}
type commitReq struct {
	Offsets map[string]int `json:"offsets"`
}
type listReq struct {
	Keys []string `json:"keys"`
}

type app struct {
	n  *maelstrom.Node
	kv *maelstrom.KV
}

func main() {
	n := maelstrom.NewNode()
	a := &app{n: n, kv: maelstrom.NewLinKV(n)}
	n.Handle("send", a.send)
	n.Handle("poll", a.poll)
	n.Handle("commit_offsets", a.commit)
	n.Handle("list_committed_offsets", a.list)
	if err := n.Run(); err != nil {
		log.Fatal(err)
	}
}

func ctx() (context.Context, context.CancelFunc) {
	return context.WithTimeout(context.Background(), 30*time.Second)
}

func (a *app) send(m maelstrom.Message) error {
	var r sendReq
	if err := json.Unmarshal(m.Body, &r); err != nil {
		return err
	}
	c, cancel := ctx()
	defer cancel()
	key := logPrefix + r.Key
	for {
		var vals []json.RawMessage
		err := a.kv.ReadInto(c, key, &vals)
		if err != nil && maelstrom.ErrorCode(err) != maelstrom.KeyDoesNotExist {
			return err
		}
		if err != nil {
			vals = nil
		}
		oldLen := len(vals)
		next := make([]json.RawMessage, oldLen+1)
		copy(next, vals)
		copy(next[oldLen:], r.Msg)
		err = a.kv.CompareAndSwap(c, key, vals, next, true)
		if err == nil {
			return a.n.Reply(m, map[string]any{"type": "send_ok", "offset": oldLen})
		}
		if maelstrom.ErrorCode(err) != maelstrom.PreconditionFailed {
			return err
		}
	}
}

type onePoll struct {
	key   string
	items []pair
	err   error
}

func (a *app) poll(m maelstrom.Message) error {
	var r pollReq
	if err := json.Unmarshal(m.Body, &r); err != nil {
		return err
	}
	c, cancel := ctx()
	defer cancel()
	ch := make(chan onePoll, len(r.Offsets))
	var wg sync.WaitGroup
	for key, requested := range r.Offsets {
		wg.Add(1)
		go func(key string, requested int) {
			defer wg.Done()
			var vals []json.RawMessage
			err := a.kv.ReadInto(c, logPrefix+key, &vals)
			if err != nil {
				if maelstrom.ErrorCode(err) == maelstrom.KeyDoesNotExist {
					ch <- onePoll{key: key}
				} else {
					ch <- onePoll{key: key, err: err}
				}
				return
			}
			if requested < 0 {
				requested = 0
			}
			if requested >= len(vals) {
				ch <- onePoll{key: key}
				return
			}
			end := requested + maxPoll
			if end > len(vals) {
				end = len(vals)
			}
			items := make([]pair, 0, end-requested)
			for i := requested; i < end; i++ {
				items = append(items, pair{offset: i, value: vals[i]})
			}
			ch <- onePoll{key: key, items: items}
		}(key, requested)
	}
	wg.Wait()
	close(ch)
	msgs := map[string][]pair{}
	for p := range ch {
		if p.err != nil {
			return p.err
		}
		if len(p.items) != 0 {
			msgs[p.key] = p.items
		}
	}
	return a.n.Reply(m, map[string]any{"type": "poll_ok", "msgs": msgs})
}

func (a *app) commit(m maelstrom.Message) error {
	var r commitReq
	if err := json.Unmarshal(m.Body, &r); err != nil {
		return err
	}
	if len(r.Offsets) == 0 {
		return a.n.Reply(m, map[string]any{"type": "commit_offsets_ok"})
	}
	c, cancel := ctx()
	defer cancel()
	for {
		var committed map[string]int
		err := a.kv.ReadInto(c, commitKey, &committed)
		if err != nil {
			if maelstrom.ErrorCode(err) != maelstrom.KeyDoesNotExist {
				return err
			}
			committed = map[string]int{}
		}
		next := make(map[string]int, len(committed)+len(r.Offsets))
		for k, v := range committed {
			next[k] = v
		}
		for k, v := range r.Offsets {
			if old, ok := next[k]; !ok || v > old {
				next[k] = v
			}
		}
		err = a.kv.CompareAndSwap(c, commitKey, committed, next, true)
		if err == nil {
			return a.n.Reply(m, map[string]any{"type": "commit_offsets_ok"})
		}
		if maelstrom.ErrorCode(err) != maelstrom.PreconditionFailed {
			return err
		}
	}
}

func (a *app) list(m maelstrom.Message) error {
	var r listReq
	if err := json.Unmarshal(m.Body, &r); err != nil {
		return err
	}
	c, cancel := ctx()
	defer cancel()
	var committed map[string]int
	err := a.kv.ReadInto(c, commitKey, &committed)
	if err != nil && maelstrom.ErrorCode(err) != maelstrom.KeyDoesNotExist {
		return err
	}
	out := map[string]int{}
	for _, k := range r.Keys {
		if v, ok := committed[k]; ok {
			out[k] = v
		}
	}
	return a.n.Reply(m, map[string]any{"type": "list_committed_offsets_ok", "offsets": out})
}

